public class CategoryPlot_removeRangeMarker_TriageGen1Test {

    private CategoryPlot plot;
    private Marker mockMarker;

    @Before
    public void setUp() {
        plot = new CategoryPlot();
        mockMarker = Mockito.mock(Marker.class);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRemoveRangeMarker_NullMarker_ThrowsException() {
        plot.removeRangeMarker(0, null, Layer.FOREGROUND, true);
    }

    @Test
    public void testRemoveRangeMarker_MarkersListIsNull_ReturnsTrue() throws Exception {
        // Setup: inject empty maps to simulate no markers at index
        injectMarkersMap(plot, Layer.FOREGROUND, new HashMap<>());
        injectMarkersMap(plot, Layer.BACKGROUND, new HashMap<>());

        // If the map returns null for the index, it returns true per code logic
        assertTrue(plot.removeRangeMarker(0, mockMarker, Layer.FOREGROUND, true));
        assertTrue(plot.removeRangeMarker(0, mockMarker, Layer.BACKGROUND, true));
    }

    @Test
    public void testRemoveRangeMarker_Foreground_SuccessfulRemoval() throws Exception {
        ArrayList<Marker> markersList = new ArrayList<>();
        markersList.add(mockMarker);

        Map<Integer, ArrayList> foregroundMap = new HashMap<>();
        foregroundMap.put(0, markersList);
        injectMarkersMap(plot, Layer.FOREGROUND, foregroundMap);

        boolean result = plot.removeRangeMarker(0, mockMarker, Layer.FOREGROUND, true);

        assertTrue("Should return true when marker is removed", result);
        assertTrue("List should be empty", markersList.isEmpty());
    }

    @Test
    public void testRemoveRangeMarker_Foreground_FailedRemoval() throws Exception {
        ArrayList<Marker> markersList = new ArrayList<>();
        markersList.add(Mockito.mock(Marker.class)); // different marker

        Map<Integer, ArrayList> foregroundMap = new HashMap<>();
        foregroundMap.put(0, markersList);
        injectMarkersMap(plot, Layer.FOREGROUND, foregroundMap);

        boolean result = plot.removeRangeMarker(0, mockMarker, Layer.FOREGROUND, true);

        assertFalse("Should return false when marker is not found", result);
        assertEquals(1, markersList.size());
    }

    @Test
    public void testRemoveRangeMarker_Background_SuccessfulRemoval() throws Exception {
        ArrayList<Marker> markersList = new ArrayList<>();
        markersList.add(mockMarker);

        Map<Integer, ArrayList> backgroundMap = new HashMap<>();
        backgroundMap.put(0, markersList);
        injectMarkersMap(plot, Layer.BACKGROUND, backgroundMap);

        boolean result = plot.removeRangeMarker(0, mockMarker, Layer.BACKGROUND, true);

        assertTrue(result);
        assertTrue(markersList.isEmpty());
    }

    @Test
    public void testRemoveRangeMarker_NotifyFalse_NoException() throws Exception {
        // This tests the branch where removed is true but notify is false
        ArrayList<Marker> markersList = new ArrayList<>();
        markersList.add(mockMarker);

        Map<Integer, ArrayList> foregroundMap = new HashMap<>();
        foregroundMap.put(0, markersList);
        injectMarkersMap(plot, Layer.FOREGROUND, foregroundMap);

        // We don't mock fireChangeEvent because it's a private/protected method in the actual class,
        // but we ensure the logic path is covered.
        boolean result = plot.removeRangeMarker(0, mockMarker, Layer.FOREGROUND, false);

        assertTrue(result);
    }

    /**
     * Helper method to inject markers maps into the private fields of CategoryPlot using reflection.
     */
    @SuppressWarnings("unchecked")
    private void injectMarkersMap(CategoryPlot plot, Layer layer, Map<Integer, ArrayList> map) throws Exception {
        String fieldName = (layer == Layer.FOREGROUND) ? "foregroundRangeMarkers" : "backgroundRangeMarkers";
        Field field = CategoryPlot.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(plot, map);
    }
}
